Here is the commit message:
spi: stm32: fix excluded_middle.cocci warnings

drivers/spi/spi-stm32.c:915:23-25: WARNING !A || A && B is equivalent to !A || B

 Condition !A || A && B is equivalent to !A || B.

Generated by: scripts/coccinelle/misc/excluded_middle.cocci

Fixes: 7ceb0b8a3ced ("spi: stm32: finalize message either on dma callback or EOT")
CC: Alain Volmat <alain.volmat@foss.st.com>
Reported-by: kernel test robot <lkp@intel.com>
Signed-off-by: kernel test robot <lkp@intel.com>
Reviewed-by: Alain Volmat <alain.volmat@foss.st.com>
Link: https://lore.kernel.org/r/20210713191004.GA14729@5eb5c2cbef84
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug was caused by a complex conditional expression in the `stm32h7_spi_irq_thread` function that was unnecessarily convoluted, leading to potential misunderstandings about the logic flow. The condition `!A || A && B` was equivalent to `!A || B`, which could lead to confusion and maintenance issues. This complexity was flagged by the `excluded_middle.cocci` script as a warning, indicating that the code could be simplified without changing its behavior.

Here is the patch:
  */
 static irqreturn_t stm32h7_spi_irq_thread(int irq, void *dev_id)
 {
 	struct spi_master *master = dev_id;
 	struct stm32_spi *spi = spi_master_get_devdata(master);
 	u32 sr, ier, mask;
 	unsigned long flags;
 	bool end = false;

 	spin_lock_irqsave(&spi->lock, flags);

 	sr = readl_relaxed(spi->base + STM32H7_SPI_SR);
 	ier = readl_relaxed(spi->base + STM32H7_SPI_IER);

 	mask = ier;
 	/*
 	 * EOTIE enables irq from EOT, SUSP and TXC events. We need to set
 	 * SUSP to acknowledge it later. TXC is automatically cleared
 	 */

 	mask |= STM32H7_SPI_SR_SUSP;
 	/*
 	 * DXPIE is set in Full-Duplex, one IT will be raised if TXP and RXP
 	 * are set. So in case of Full-Duplex, need to poll TXP and RXP event.
 	 */
 	if ((spi->cur_comm == SPI_FULL_DUPLEX) && !spi->cur_usedma)
 		mask |= STM32H7_SPI_SR_TXP | STM32H7_SPI_SR_RXP;

 	if (!(sr & mask)) {
 		dev_warn(spi->dev, "spurious IT (sr=0x%08x, ier=0x%08x)\n",
 			 sr, ier);
 		spin_unlock_irqrestore(&spi->lock, flags);
 		return IRQ_NONE;
 	}

 	if (sr & STM32H7_SPI_SR_SUSP) {
 		static DEFINE_RATELIMIT_STATE(rs,
 					      DEFAULT_RATELIMIT_INTERVAL * 10,
 					      1);
 		if (__ratelimit(&rs))
 			dev_dbg_ratelimited(spi->dev, "Communication suspended\n");
 		if (!spi->cur_usedma && (spi->rx_buf && (spi->rx_len > 0)))
 			stm32h7_spi_read_rxfifo(spi);
 		/*
 		 * If communication is suspended while using DMA, it means
 		 * that something went wrong, so stop the current transfer
 		 */
 		if (spi->cur_usedma)
 			end = true;
 	}

 	if (sr & STM32H7_SPI_SR_MODF) {
 		dev_warn(spi->dev, "Mode fault: transfer aborted\n");
 		end = true;
 	}

 	if (sr & STM32H7_SPI_SR_OVR) {
 		dev_err(spi->dev, "Overrun: RX data lost\n");
 		end = true;
 	}

 	if (sr & STM32H7_SPI_SR_EOT) {
 		if (!spi->cur_usedma && (spi->rx_buf && (spi->rx_len > 0)))
 			stm32h7_spi_read_rxfifo(spi);
 		if (!spi->cur_usedma ||
-		    (spi->cur_usedma && (spi->cur_comm == SPI_SIMPLEX_TX ||
-		     spi->cur_comm == SPI_3WIRE_TX)))
+		    (spi->cur_comm == SPI_SIMPLEX_TX || spi->cur_comm == SPI_3WIRE_TX))
 			end = true;
 	}

 	if (sr & STM32H7_SPI_SR_TXP)
 		if (!spi->cur_usedma && (spi->tx_buf && (spi->tx_len > 0)))
 			stm32h7_spi_write_txfifo(spi);

 	if (sr & STM32H7_SPI_SR_RXP)
 		if (!spi->cur_usedma && (spi->rx_buf && (spi->rx_len > 0)))
 			stm32h7_spi_read_rxfifo(spi);

 	writel_relaxed(sr & mask, spi->base + STM32H7_SPI_IFCR);

 	spin_unlock_irqrestore(&spi->lock, flags);

 	if (end) {
 		stm32h7_spi_disable(spi);
 		spi_finalize_current_transfer(master);
 	}

 	return IRQ_HANDLED;
 }



